package com.example.smartpantrymanager.ui;
import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import androidx.recyclerview.widget.*;import com.example.smartpantrymanager.R;import com.example.smartpantrymanager.adapter.RecipeAdapter;import com.example.smartpantrymanager.data.DatabaseHelper;import com.example.smartpantrymanager.model.Recipe;import java.util.*;
public class SuggestedRecipesActivity extends AppCompatActivity implements RecipeAdapter.Listener{DatabaseHelper db;RecipeAdapter a;TextView empty;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_suggested);db=new DatabaseHelper(this);empty=findViewById(R.id.noMatches);RecyclerView r=findViewById(R.id.recyclerRecipes);r.setLayoutManager(new LinearLayoutManager(this));a=new RecipeAdapter(new ArrayList<>(),this);r.setAdapter(a);} @Override protected void onResume(){super.onResume();load();}void load(){List<Recipe> x=db.getStrictMatches();a=new RecipeAdapter(x,this);((RecyclerView)findViewById(R.id.recyclerRecipes)).setAdapter(a);empty.setVisibility(x.isEmpty()?View.VISIBLE:View.GONE);}public void open(Recipe r){Intent i=new Intent(this,RecipeDetailActivity.class);i.putExtra("id",r.getId());startActivity(i);}}
